import unittest
from exporter import export_record
class ExportTests(unittest.TestCase):
    def test_same_workspace(self):
        self.assertEqual(export_record({"permissions":["reports:download"],"workspace":1},{"workspace":1,"amount":10}),{"amount":10})
    def test_forbidden(self):
        with self.assertRaises(PermissionError):
            export_record({"permissions":[],"workspace":1},{"workspace":1,"amount":10})

    def test_foreign_workspace(self):
        user = {"permissions": ["reports:download"], "workspace": 1}
        record = {"workspace": 2, "amount": 10}

        with self.assertRaises(PermissionError):
            export_record(user, record)

    def test_unknown_output_format(self):
        user = {"permissions": ["reports:download"], "workspace": 1}
        record = {"workspace": 1, "amount": 10}

        with self.assertRaises(ValueError):
            export_record(user, record, output_format="csv")

    def test_permission_checked_before_record_access(self):
        user = {"permissions": [], "workspace": 1}

        with self.assertRaises(PermissionError):
            export_record(user, {})

